require_once __DIR__.'/_data.php';$db=storefront_db();$customer=$db?marketplace_customer($db):null;if(!$customer)legacy_redirect('masuk?next=pesanan-saya');$cid=(int)$customer['id'];$status=trim((string)($_GET['status']??''));$allowed=['pending_payment','paid','processing','shipped','completed','expired','cancelled'];$where='customer_id=?';$params=[$cid];if(in_array($status,$allowed,true)){$where.=' AND order_status=?';$params[]=$status;}$page=max(1,(int)($_GET['page']??1));$per=15;$st=$db->prepare("SELECT COUNT(*) FROM online_orders WHERE $where");$st->execute($params);$meta=pagination_meta((int)$st->fetchColumn(),$page,$per);$q=$db->prepare("SELECT * FROM online_orders WHERE $where ORDER BY id DESC LIMIT {$meta['perPage']} OFFSET {$meta['offset']}");$q->execute($params);$orders=$q->fetchAll()?:[];$pageTitle='Pesanan Saya';$activePage='account';require __DIR__.'/_header.php';
?>
